/* CSS Reset & Variables */
:root {
  --bg-color: #2b2b36;
  --card-bg: #f4ede2;
  --pixel-dark: #1f1f29;
  --accent: #507dbc;
  --accent-hover: #3d6499;
  --fixed-color: #1f1f29;
  --user-color: #2e5a88;
  --conflict-bg: #ff6b6b;
  --conflict-text: #ffffff;
  --solved-bg: #48bb78;
  --solved-text: #ffffff;
  --border-thick: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background-color: var(--bg-color);
  color: var(--pixel-dark);
  font-family: 'Courier New', Courier, monospace, monospace;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  background-color: var(--card-bg);
  border: var(--border-thick) solid var(--pixel-dark);
  box-shadow: 6px 6px 0px 0px var(--pixel-dark);
  width: 100%;
  max-width: 440px;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.game-header {
  text-align: center;
}

.title {
  font-size: 24px;
  font-weight: 900;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--pixel-dark);
}

.subtitle {
  font-size: 14px;
  color: #666;
  margin-top: 4px;
}

.status-area {
  min-height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
}

.banner {
  background-color: var(--solved-bg);
  color: var(--solved-text);
  font-size: 20px;
  font-weight: bold;
  padding: 6px 16px;
  border: 3px solid var(--pixel-dark);
  box-shadow: 3px 3px 0px 0px var(--pixel-dark);
  animation: pop 0.2s ease-out;
}

@keyframes pop {
  0% { transform: scale(0.8); }
  100% { transform: scale(1); }
}

.info-text {
  font-size: 14px;
  color: #444;
  text-align: center;
}

.board-wrapper {
  padding: 4px;
  background: var(--pixel-dark);
  border: 2px solid var(--pixel-dark);
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 60px);
  grid-template-rows: repeat(4, 60px);
  background-color: var(--pixel-dark);
  gap: 2px;
}

.cell {
  background-color: #ffffff;
  border: none;
  font-family: inherit;
  font-size: 28px;
  font-weight: bold;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  color: var(--user-color);
  user-select: none;
  outline: none;
  transition: background-color 0.1s;
}

/* 2x2 Box Divider Accents */
.cell[data-col="1"] {
  margin-right: 2px;
}
.cell[data-row="1"] {
  margin-bottom: 2px;
}

.cell.fixed {
  background-color: #e9e4d9;
  color: var(--fixed-color);
  cursor: default;
}

.cell:focus-visible {
  outline: 3px solid var(--accent);
  z-index: 2;
}

.cell.selected:not(.conflict) {
  background-color: #dcedfc;
}

.cell.conflict {
  background-color: var(--conflict-bg) !important;
  color: var(--conflict-text) !important;
}

.controls {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.keypad {
  display: flex;
  gap: 8px;
  width: 100%;
  justify-content: center;
}

.pixel-btn {
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  background-color: var(--accent);
  color: #ffffff;
  border: 3px solid var(--pixel-dark);
  box-shadow: 3px 3px 0px 0px var(--pixel-dark);
  padding: 8px 12px;
  cursor: pointer;
  outline: none;
  transition: transform 0.05s, box-shadow 0.05s;
}

.num-btn {
  min-width: 48px;
}

.action-btn {
  font-size: 14px;
  padding: 8px 16px;
  background-color: #e2e8f0;
  color: var(--pixel-dark);
}

.pixel-btn:hover {
  background-color: var(--accent-hover);
  color: #fff;
}

.action-btn:hover {
  background-color: #cbd5e1;
  color: var(--pixel-dark);
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px 0px var(--pixel-dark);
}

.pixel-btn:focus-visible {
  outline: 2px dashed var(--pixel-dark);
  outline-offset: 2px;
}

.instructions {
  font-size: 12px;
  color: #555;
  text-align: center;
}

@media (max-width: 380px) {
  .grid {
    grid-template-columns: repeat(4, 50px);
    grid-template-rows: repeat(4, 50px);
  }
  .cell {
    font-size: 22px;
  }
  .num-btn {
    min-width: 40px;
    padding: 6px 8px;
    font-size: 16px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Built-in puzzle configuration (0 = empty)
  // Solvable unique 4x4 configuration:
  // 1 . | . 4
  // . 2 | 3 .
  // ----+----
  // . 3 | 2 .
  // 2 . | . 1
  const INITIAL_BOARD = [
    [1, 0, 0, 4],
    [0, 2, 3, 0],
    [0, 3, 2, 0],
    [2, 0, 0, 1]
  ];

  let gridState = JSON.parse(JSON.stringify(INITIAL_BOARD));
  let selectedRow = 0;
  let selectedCol = 1;

  const gridElement = document.getElementById('sudoku-grid');
  const solvedBanner = document.getElementById('solved-banner');
  const infoMsg = document.getElementById('info-msg');
  const restartBtn = document.getElementById('btn-restart');
  const numButtons = document.querySelectorAll('.num-btn');

  function initGrid() {
    gridElement.innerHTML = '';
    for (let r = 0; r < 4; r++) {
      for (let c = 0; c < 4; c++) {
        const cellBtn = document.createElement('button');
        cellBtn.type = 'button';
        cellBtn.className = 'cell';
        cellBtn.dataset.row = r;
        cellBtn.dataset.col = c;
        cellBtn.setAttribute('role', 'gridcell');
        cellBtn.setAttribute('aria-label', `Row ${r + 1}, Column ${c + 1}`);

        if (INITIAL_BOARD[r][c] !== 0) {
          cellBtn.classList.add('fixed');
          cellBtn.textContent = INITIAL_BOARD[r][c];
          cellBtn.setAttribute('aria-readonly', 'true');
        } else {
          cellBtn.addEventListener('click', () => {
            selectCell(r, c);
          });
        }

        cellBtn.addEventListener('keydown', handleCellKeyDown);
        gridElement.appendChild(cellBtn);
      }
    }
    selectCell(0, 1);
    updateBoardView();
  }

  function selectCell(r, c) {
    selectedRow = r;
    selectedCol = c;
    updateSelectionVisuals();
  }

  function updateSelectionVisuals() {
    const cells = gridElement.querySelectorAll('.cell');
    cells.forEach(cell => {
      const r = parseInt(cell.dataset.row, 10);
      const c = parseInt(cell.dataset.col, 10);
      if (r === selectedRow && c === selectedCol) {
        cell.classList.add('selected');
      } else {
        cell.classList.remove('selected');
      }
    });
  }

  function setCellValue(val) {
    if (INITIAL_BOARD[selectedRow][selectedCol] !== 0) return;
    gridState[selectedRow][selectedCol] = val;
    updateBoardView();
  }

  function findConflicts() {
    const conflicts = Array(4).fill(null).map(() => Array(4).fill(false));

    // 1. Check Rows
    for (let r = 0; r < 4; r++) {
      const seen = {};
      for (let c = 0; c < 4; c++) {
        const val = gridState[r][c];
        if (val !== 0) {
          if (seen[val] !== undefined) {
            conflicts[r][c] = true;
            conflicts[r][seen[val]] = true;
          } else {
            seen[val] = c;
          }
        }
      }
    }

    // 2. Check Columns
    for (let c = 0; c < 4; c++) {
      const seen = {};
      for (let r = 0; r < 4; r++) {
        const val = gridState[r][c];
        if (val !== 0) {
          if (seen[val] !== undefined) {
            conflicts[r][c] = true;
            conflicts[seen[val]][c] = true;
          } else {
            seen[val] = r;
          }
        }
      }
    }

    // 3. Check 2x2 Boxes
    for (let br = 0; br < 4; br += 2) {
      for (let bc = 0; bc < 4; bc += 2) {
        const seen = {};
        for (let r = br; r < br + 2; r++) {
          for (let c = bc; c < bc + 2; c++) {
            const val = gridState[r][c];
            if (val !== 0) {
              if (seen[val]) {
                conflicts[r][c] = true;
                conflicts[seen[val].r][seen[val].c] = true;
              } else {
                seen[val] = { r, c };
              }
            }
          }
        }
      }
    }

    return conflicts;
  }

  function updateBoardView() {
    const conflicts = findConflicts();
    let hasEmpty = false;
    let hasConflict = false;

    const cells = gridElement.querySelectorAll('.cell');
    cells.forEach(cell => {
      const r = parseInt(cell.dataset.row, 10);
      const c = parseInt(cell.dataset.col, 10);
      const val = gridState[r][c];

      cell.textContent = val === 0 ? '' : val;

      if (conflicts[r][c]) {
        cell.classList.add('conflict');
        hasConflict = true;
      } else {
        cell.classList.remove('conflict');
      }

      if (val === 0) hasEmpty = true;
    });

    if (!hasEmpty && !hasConflict) {
      solvedBanner.removeAttribute('hidden');
      infoMsg.setAttribute('hidden', '');
    } else {
      solvedBanner.setAttribute('hidden', '');
      infoMsg.removeAttribute('hidden');
    }
  }

  function handleCellKeyDown(e) {
    const r = parseInt(e.target.dataset.row, 10);
    const c = parseInt(e.target.dataset.col, 10);

    if (['1', '2', '3', '4'].includes(e.key)) {
      selectCell(r, c);
      setCellValue(parseInt(e.key, 10));
    } else if (e.key === 'Backspace' || e.key === 'Delete' || e.key === '0') {
      selectCell(r, c);
      setCellValue(0);
    } else if (e.key === 'ArrowUp' && r > 0) {
      selectCell(r - 1, c);
      focusSelectedCell();
    } else if (e.key === 'ArrowDown' && r < 3) {
      selectCell(r + 1, c);
      focusSelectedCell();
    } else if (e.key === 'ArrowLeft' && c > 0) {
      selectCell(r, c - 1);
      focusSelectedCell();
    } else if (e.key === 'ArrowRight' && c < 3) {
      selectCell(r, c + 1);
      focusSelectedCell();
    }
  }

  function focusSelectedCell() {
    const cell = gridElement.querySelector(`.cell[data-row="${selectedRow}"][data-col="${selectedCol}"]`);
    if (cell) cell.focus();
  }

  // Keypad controls
  numButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      const val = btn.dataset.val;
      setCellValue(val === '' ? 0 : parseInt(val, 10));
    });
  });

  // Global key listener for direct keypad typing
  document.addEventListener('keydown', (e) => {
    if (['1', '2', '3', '4'].includes(e.key)) {
      setCellValue(parseInt(e.key, 10));
    } else if (e.key === 'Backspace' || e.key === 'Delete') {
      setCellValue(0);
    }
  });

  // Restart button
  restartBtn.addEventListener('click', () => {
    gridState = JSON.parse(JSON.stringify(INITIAL_BOARD));
    selectCell(0, 1);
    updateBoardView();
  });

  initGrid();
});
